const t = (x: any) => x.kind === "foreground" ? (x.stdout.text + (x.stderr.text || "")) : JSON.stringify(x);
const [codexDir, cuaGrep, ver] = await Promise.all([
 tools.pwsh({ command: `Get-ChildItem -Force 'C:\\Users\\jjq21\\AppData\\Local\\OpenAI\\Codex' -ErrorAction SilentlyContinue | Select-Object Mode,Name | Format-Table -AutoSize | Out-String -Width 200
echo '=== runtimes ==='
Get-ChildItem -Force 'C:\\Users\\jjq21\\AppData\\Local\\OpenAI\\Codex\\runtimes' -ErrorAction SilentlyContinue | Select-Object Mode,Name | Format-Table -AutoSize | Out-String -Width 200
echo '=== cua_node bin ==='
Get-ChildItem -Force 'C:\\Users\\jjq21\\AppData\\Local\\OpenAI\\Codex\\runtimes\\cua_node' -ErrorAction SilentlyContinue | Select-Object -First 20 Name | Format-Table -AutoSize | Out-String -Width 200`, description: "Inspect Codex install for CUA runtime" }),
 tools.pwsh({ command: `$p='C:\\Users\\jjq21\\AppData\\Local\\OpenAI\\Codex\\runtimes\\cua_node'
Get-ChildItem -Path $p -Recurse -Depth 6 -ErrorAction SilentlyContinue | Where-Object { $_.Name -match 'cua|computer|screen|screenshot|mouse|keyboard|automat' } | Select-Object -First 40 FullName | Format-Table -AutoSize | Out-String -Width 250`, description: "Find computer-use modules in Codex runtime" }),
 tools.pwsh({ command: `codex --version 2>&1 | Select-Object -First 3; echo '--- where ---'; (Get-Command codex -ErrorAction SilentlyContinue).Source; echo '--- codex home ---'; Get-ChildItem -Force 'C:\\Users\\jjq21\\.codex' -ErrorAction SilentlyContinue | Select-Object Mode,Name | Format-Table -AutoSize | Out-String -Width 200`, description: "Check codex CLI version and home" }),
]);
console.log("### Codex dir\n" + t(codexDir).slice(0, 2500));
console.log("\n### CUA modules\n" + t(cuaGrep).slice(0, 2500));
console.log("\n### codex CLI\n" + t(ver).slice(0, 2000));
